mapper.sql:
1 = 1

    AND sr.status = #{status}


    AND sr.company_id = #{companyId}


    AND sr.job_category_id = #{jobCategoryId}


    AND sr.career_years <= 1
    AND sr.career_years BETWEEN 2 AND 3
    AND sr.career_years BETWEEN 4 AND 7
    AND sr.career_years >= 8


    AND (c.company_name LIKE CONCAT('%', #{keyword}, '%')
         OR jc.category_name LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT sr.*, c.company_name AS companyName, jc.category_name AS categoryName, (SELECT COUNT(*) FROM salary_records sample WHERE sample.company_id = sr.company_id AND sample.job_category_id = sr.job_category_id AND sample.career_years = sr.career_years AND sample.salary_year = sr.salary_year AND sample.status = '정상') AS sampleCount FROM salary_records sr JOIN companies c ON c.company_id = sr.company_id JOIN job_categories jc ON jc.job_category_id = sr.job_category_id WHERE
ORDER BY sr.created_at ASC ORDER BY sr.base_salary DESC, sr.created_at DESC ORDER BY sr.base_salary ASC, sr.created_at DESC ORDER BY c.company_name ASC, sr.created_at DESC ORDER BY sr.created_at DESC
LIMIT #{offset}, #{pageSize}
